using System.Text.Json;
using PortableDocument.Content;
using Xunit;

namespace AdoBye.Tests;

/// <summary>
/// Compares the native component planes of JpxCodestream against OpenJPEG 2.5.4 (opj_decompress, PGX per component
/// at native depth). Fixtures and exact command lines: tests/fixtures/jpxopj (manifest.json), generated by
/// tools/make_jpx_opj_matrix.py. Planes hold unsigned samples (signed data is stored offset by 2^(depth-1)) and at most
/// the top 16 bits of deeper components.
/// </summary>
public class JpxOpjMatrixTests
{
    static string Dir => Path.Combine(AppContext.BaseDirectory, "fixtures", "jpxopj");

    public static IEnumerable<object[]> Cases() =>
        Directory.GetFiles(Dir, "*.j2k").Select(p => new object[] { Path.GetFileNameWithoutExtension(p) }).OrderBy(a => (string)a[0]);

    static (int[] Samples, int W, int H, int Prec, bool Signed) ReadPgx(string path)
    {
        var raw = File.ReadAllBytes(path);
        var nl = Array.IndexOf(raw, (byte)'\n');
        var parts = System.Text.Encoding.ASCII.GetString(raw, 0, nl).Split(' ', StringSplitOptions.RemoveEmptyEntries);
        var signed = parts[2] == "-";
        int prec = int.Parse(parts[3]), w = int.Parse(parts[4]), h = int.Parse(parts[5]);
        var size = prec <= 8 ? 1 : prec <= 16 ? 2 : 4;
        var s = new int[w * h];
        for (var i = 0; i < s.Length; i++)
        {
            long v = 0;
            for (var b = 0; b < size; b++) v = v << 8 | raw[nl + 1 + i * size + b];
            if (signed && (v & (1L << (size * 8 - 1))) != 0) v -= 1L << (size * 8);
            s[i] = (int)v;
        }
        return (s, w, h, prec, signed);
    }

    [Theory]
    [MemberData(nameof(Cases))]
    public void PlanesMatchOpenJpegOutput(string name)
    {
        using var meta = JsonDocument.Parse(File.ReadAllText(Path.Combine(Dir, name + ".meta")));
        var tol = meta.RootElement.GetProperty("tolerance").GetInt32();
        var count = meta.RootElement.GetProperty("components").GetInt32();
        var data = File.ReadAllBytes(Path.Combine(Dir, name + ".j2k"));
        var cs = new JpxCodestream();
        if (meta.RootElement.GetProperty("expect").GetString() == "reject")
        {
            // Documented disagreement: OpenJPEG decodes leniently, this decoder reports the malformed stream.
            Assert.False(cs.Decode(data, 0, data.Length));
            Assert.False(string.IsNullOrEmpty(cs.Warning));
            return;
        }
        Assert.True(cs.Decode(data, 0, data.Length), name + ": " + cs.Warning);
        Assert.Null(cs.Warning);
        Assert.Equal(count, cs.Csiz);

        long bad = 0; var max = 0;
        var first = new List<string>();
        for (var c = 0; c < count; c++)
        {
            var (samples, w, h, prec, signed) = ReadPgx(Path.Combine(Dir, $"{name}.c{c}.pgx"));
            Assert.Equal(cs.Depth[c], prec);
            Assert.Equal(cs.Signed[c], signed);
            Assert.Equal(w, cs.CW[c]);
            Assert.Equal(h, cs.CH[c]);
            var shift = Math.Max(0, prec - 16);
            var bias = signed ? 1 << (Math.Min(prec, 16) - 1) : 0;
            var plane = cs.Planes[c];
            for (var i = 0; i < samples.Length; i++)
            {
                var expected = (samples[i] >> shift) + bias;
                var diff = Math.Abs(plane[i] - expected);
                if (diff > tol) { bad++; if (first.Count < 8) first.Add($"c{c}({i % w},{i / w}) got {plane[i]} want {expected}"); }
                if (diff > max) max = diff;
            }
        }
        Assert.True(bad == 0, $"{name}: {bad} samples differ from OpenJPEG by more than {tol} (max diff {max}): {string.Join("; ", first)}");
    }
}
